/* v2.8 reward settlement. Guarded by duel.ended: exactly one award per match. */
completeDuel24=function(outcome){const d=duel24;if(!d||d.ended)return;d.ended=true;d.outcome=outcome;d.reward=0;d.ticket28=null;const w=wallet24();w.pendingBattle=false;if(outcome==='win'){w.wins++;d.reward=BATTLE_REWARDS28[d.mode||'solo'].points;w.points+=d.reward;w.earned+=d.reward;d.ticket28=rollTicket28(d.mode||'solo');if(d.ticket28)grantTicket28(save,d.ticket28);d.result='勝利！ 次の時空防衛戦へ。';audioSys.sfx('clear');}else if(outcome==='loss'){w.losses++;d.result='惜敗… 次の一投に、希望を。';audioSys.sfx('over');}else{w.draws++;d.result='引き分け！ 互いに見事な一撃。';audioSys.sfx('card');}persist();renderWallet24();audioSys.set('title');};
const setupBefore28=renderBattleSetup24;
renderBattleSetup24=function(){setupBefore28();$('#battleRecord24').textContent=`${wallet24().wins}勝 ${wallet24().losses}敗 ${wallet24().draws}引き分け ／ このモードの勝利報酬 ＋${BATTLE_REWARDS28[save.teamBattle27.mode].points} pt ／ チケット ${Math.round(BATTLE_REWARDS28[save.teamBattle27.mode].chance*100)}%`;};
const renderDuelBefore28=renderDuel24;
renderDuel24=function(){renderDuelBefore28();const d=duel24;if(!d?.ended)return;const p=$('#duelFinish24 > p');if(p){p.textContent=d.outcome==='win'?`勝利報酬 ＋${fmt(d.reward)} 時空ポイント`:'今回の時空ポイント報酬は0 pt。編成や作戦を変えて挑もう。';if(d.ticket28){const item=ITEMS28[d.ticket28];p.insertAdjacentHTML('afterend',`<div class="ticket-reward28"><small>さらに……</small><strong>${supportIcon28('ticket')} ITEM GET!</strong><b>${item.icon} ${item.name} ×1</b><span>次の時空防衛戦へ、支援を持ち込もう。</span></div>`);}}};
function showExchange28(){showScreen('exchange28');renderExchange28();}
function renderExchange28(){renderWallet24();$('#exchangeBalance28').textContent=fmt(save.awakening26.fragments);$('#exchangeStock28').innerHTML=Object.entries(ITEMS28).map(([id,x])=>`<article class="supply-card28"><div class="supply-icon28">${x.icon}</div><span class="eyebrow">DEFENSE SUPPORT</span><h3>${x.name}</h3><p>${x.description}</p><div class="supply-stock28">所持 <b>×${fmt(save.support28.items[id])}</b></div><button class="primary" data-exchange28="${id}" ${save.awakening26.fragments<x.cost?'disabled':''}>かけら ${x.cost}個で交換</button><small>${save.awakening26.fragments<x.cost?'かけらが足りません':'チケット1枚と交換'}</small></article>`).join('');$$('[data-exchange28]').forEach(b=>b.onclick=()=>confirmExchange28(b.dataset.exchange28));}
function confirmExchange28(id){const item=ITEMS28[id];if(!item||save.awakening26.fragments<item.cost)return;let confirmed=false;openDialog(`<div class="eyebrow">SUPPORT EXCHANGE</div><h2>${item.icon} ${item.name}</h2><p class="guide-text">時空のかけら${item.cost}個を使って、チケット1枚に交換しますか？</p><p class="mini-note">所持 ${fmt(save.awakening26.fragments)}個 → 交換後 ${fmt(save.awakening26.fragments-item.cost)}個</p><div class="modal-actions"><button id="confirmExchange28" class="primary">交換する</button><button id="cancelExchange28" class="ghost">やめる</button></div>`);$('#cancelExchange28').onclick=closeDialog;$('#confirmExchange28').onclick=()=>{if(confirmed)return;confirmed=true;if(exchangeTicket28(save,id)){persist();audioSys.sfx('card');closeDialog();renderExchange28();toast(item.name+' ×1 GET！');}else{closeDialog();renderExchange28();}};}
$$('[data-exchange-open28]').forEach(b=>b.onclick=showExchange28);$('#exchangeBack28').onclick=showSummon24;$('#exchangeTyping28').onclick=showSelect;
const introBefore28=intro;
intro=function(eraId){introBefore28(eraId);let selected=null;const box=document.createElement('div');box.className='loadout28';box.innerHTML='<h3>支援アイテムを使いますか？</h3><p>カードバトルで得た支援を、時空防衛戦へ。1プレイ1種類・1枚です。</p><div id="loadoutChoices28" class="loadout-choices28"></div><p class="mini-note">ハートは開始時に消費。時止め・防壁は発動時に消費し、未使用なら残ります。</p>';$('#dialogBox .modal-actions').before(box);const draw=()=>{$('#loadoutChoices28').innerHTML=`<button data-loadout28="none" class="${selected===null?'chosen28':''}" aria-pressed="${selected===null}"><b>使わない</b><small>いつもの防衛戦へ</small></button>`+Object.entries(ITEMS28).map(([id,x])=>`<button data-loadout28="${id}" class="${selected===id?'chosen28':''}" aria-pressed="${selected===id}" ${!save.support28.items[id]?'disabled':''}><b>${x.icon} ${x.short} ×${fmt(save.support28.items[id])}</b><small>${x.description}</small></button>`).join('');$$('[data-loadout28]').forEach(b=>b.onclick=()=>{selected=b.dataset.loadout28==='none'?null:b.dataset.loadout28;draw()});};draw();$('#startBtn').onclick=()=>{if(selected&&!save.support28.items[selected])return;closeDialog();startGame(eraId,selected);};};
$('#retryBtn').onclick=()=>intro(game.era.id);
const startGameBefore28=startGame;
startGame=function(eraId,item=null){if(item&&(!ITEMS28[item]||!save.support28.items[item]))return false;startGameBefore28(eraId);game.support28={selected:item,used:null,stopRemaining:0};save.support28.lastRun={era:eraId,selected:item,used:null};if(item==='heart'&&useRunItem28('heart')){game.hp++;game.maxHP++;toast('ハート＋1！ この防衛戦を支援');}persist();updateHUD();renderItem28();return true;};
function useRunItem28(id){const s=game?.support28;if(!s||s.selected!==id||s.used||!consumeTicket28(save,id))return false;s.used=id;save.support28.lastRun={era:game.era.id,selected:s.selected,used:id};persist();return true;}
function activateStop28(){const s=game?.support28;if(!s||game.finished||game.paused||game.transTime||currentScreen!=='battle'||s.stopRemaining>0||!useRunItem28('stop'))return false;s.stopRemaining=5;audioSys.sfx('combo');toast('時止め！ 5秒間、記憶をつなげ');renderItem28();if(game.mode==='boss')$('#answerInput').focus({preventScroll:true});else $('#battle').focus({preventScroll:true});return true;}
// Called only by active combat ticks. Pauses and between-wave explanations do not spend the five seconds.
function stepStop28(dt){const s=game?.support28;if(!s||s.stopRemaining<=0)return dt;const frozen=Math.min(dt,s.stopRemaining);s.stopRemaining=Math.max(0,s.stopRemaining-frozen);if(s.stopRemaining===0)toast('時止め終了！');return dt-frozen;}
function interceptArrival28(){if(game?.support28?.selected!=='wall'||!useRunItem28('wall'))return false;audioSys.sfx('card');toast('防壁！ ダメージを無効化');game.flash=.12;renderItem28();return true;}
let supportHudKey28='';
function renderItem28(){const el=$('#supportHud28');if(!el||!game)return;const s=game.support28;el.hidden=!s?.selected;$('#arena').classList.toggle('time-stopped28',!!s?.stopRemaining);if(!s?.selected){supportHudKey28='';return;}const x=ITEMS28[s.selected],key=[s.selected,s.used,Math.ceil(s.stopRemaining*10),game.mode,game.paused,!!game.transTime,game.finished].join('|');if(key===supportHudKey28)return;supportHudKey28=key;let detail=s.used?'使用済み':'待機中';if(s.selected==='heart')detail='このプレイのライフ ＋1';if(s.selected==='wall'&&!s.used)detail='敵到達時に1回だけ自動で防御';if(s.stopRemaining>0)detail=`敵の時間停止中　あと ${s.stopRemaining.toFixed(1)} 秒`;
 el.innerHTML=`<div><small>時空防衛・支援アイテム</small><b>${x.icon} ${x.short}</b><span aria-live="off">${detail}</span></div>${s.selected==='stop'?`<button id="activateStop28" class="primary" ${s.used||game.paused||game.transTime||game.finished?'disabled':''}>${s.used?'発動済み':supportIcon28('stop')+' 時止め ×1'}</button>`:'<span class="support-seal28">'+(s.used?'支援発動':'AUTO')+'</span>'}`;
 $('#activateStop28')?.addEventListener('click',activateStop28);
}
const updateHUDBefore28=updateHUD;updateHUD=function(){updateHUDBefore28();renderItem28();};
